local WickSpinnerMaker = {}
local PRODUCTS = {
    iron_wick_spinner = { name = "Železna predilnica za fitilje", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 150, prestige = 3, happiness = 2, description = "Železna predilnica za fitilje." },
    bronze_wick_spinner = { name = "Bronasta predilnica za fitilje", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 365, prestige = 5, happiness = 3, description = "Bronasta predilnica za tanke fitilje." },
    silver_wick_spinner = { name = "Srebrna predilnica za fitilje", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 880, prestige = 10, happiness = 4, description = "Srebrna predilnica za plemiške fitilje." },
    gilded_wick_spinner = { name = "Pozlačena predilnica za fitilje", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 1900, prestige = 19, happiness = 5, description = "Pozlačena predilnica za dvorne fitilje." },
    jewel_set_wick_spinner = { name = "Draguljasta predilnica za fitilje", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4100, prestige = 35, happiness = 7, description = "Draguljasta predilnica za kraljevske fitilje." },
    royal_sovereign_wick_spinner = { name = "Kraljevski suverena predilnica za fitilje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 8800, prestige = 67, happiness = 13, description = "Suverena predilnica z biseri za krono." },
}
local BUILDINGS = {
    wickspinner_workshop = { name = "Predilna delavnica", cost = { gold = 315, wood = 185, stone = 125, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    wickspinner_house = { name = "Predilna hiša", cost = { gold = 1165, wood = 365, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_wickspinner_atelier = { name = "Mojstrski predilni atelje", cost = { gold = 2935, wood = 425, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_wickspinner_palace = { name = "Suverena predilna palača", cost = { gold = 12780, wood = 650, stone = 820, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
WickSpinnerMaker.ironStock = 12; WickSpinnerMaker.bronzeStock = 10; WickSpinnerMaker.woodStock = 18; WickSpinnerMaker.leatherStock = 10; WickSpinnerMaker.silverStock = 8; WickSpinnerMaker.goldStock = 6; WickSpinnerMaker.jewelStock = 4; WickSpinnerMaker.pearlStock = 4
WickSpinnerMaker.productStock = {}; WickSpinnerMaker.buildings = {}; WickSpinnerMaker.maker = nil; WickSpinnerMaker.activeMaking = {}; WickSpinnerMaker.totalProducts = 0; WickSpinnerMaker.dayTimer = 0
function WickSpinnerMaker.init() WickSpinnerMaker.ironStock=12; WickSpinnerMaker.bronzeStock=10; WickSpinnerMaker.woodStock=18; WickSpinnerMaker.leatherStock=10; WickSpinnerMaker.silverStock=8; WickSpinnerMaker.goldStock=6; WickSpinnerMaker.jewelStock=4; WickSpinnerMaker.pearlStock=4; WickSpinnerMaker.productStock={}; WickSpinnerMaker.buildings={}; WickSpinnerMaker.maker=nil; WickSpinnerMaker.activeMaking={}; WickSpinnerMaker.totalProducts=0; WickSpinnerMaker.dayTimer=0; print("[WickSpinnerMaker] Royal Wick Spinner Maker System initialized (6 products, 4 buildings)") end
function WickSpinnerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WickSpinnerMaker.maker={name=n or ("Predilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predilnik najet: %s (spretnost: %d)",WickSpinnerMaker.maker.name,s),"success") end; return true end
function WickSpinnerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WickSpinnerMaker.build(id) local ok,e=WickSpinnerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WickSpinnerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WickSpinnerMaker.getQualityBonus() local b=0; for _,bd in ipairs(WickSpinnerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WickSpinnerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WickSpinnerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WickSpinnerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WickSpinnerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WickSpinnerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WickSpinnerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WickSpinnerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WickSpinnerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WickSpinnerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WickSpinnerMaker.buildings==0 then return false,"Potrebna predilna delavnica" end; if not WickSpinnerMaker.maker then return false,"Potreben predilnik" end; return true end
function WickSpinnerMaker.make(pt,qty) qty=qty or 1; local ok,e=WickSpinnerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WickSpinnerMaker.ironStock=WickSpinnerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WickSpinnerMaker.bronzeStock=WickSpinnerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WickSpinnerMaker.woodStock=WickSpinnerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WickSpinnerMaker.leatherStock=WickSpinnerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WickSpinnerMaker.silverStock=WickSpinnerMaker.silverStock-d.silverCost*qty end; if d.goldCost then WickSpinnerMaker.goldStock=WickSpinnerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WickSpinnerMaker.jewelStock=WickSpinnerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WickSpinnerMaker.pearlStock=WickSpinnerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WickSpinnerMaker.maker then t=math.max(1,t-math.floor(WickSpinnerMaker.maker.skill/13)) end; table.insert(WickSpinnerMaker.activeMaking,{id="wickspinner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WickSpinnerMaker.completeMaking(m) local q=1.0+(WickSpinnerMaker.getQualityBonus()/100); if WickSpinnerMaker.maker then q=q+(WickSpinnerMaker.maker.skill/140) end; q=math.min(2.5,q); WickSpinnerMaker.productStock[m.productType]=(WickSpinnerMaker.productStock[m.productType] or 0)+m.quantity; WickSpinnerMaker.totalProducts=WickSpinnerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WickSpinnerMaker.maker then WickSpinnerMaker.maker.itemsMade=WickSpinnerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WickSpinnerMaker.maker.skill=math.min(100,WickSpinnerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Predilnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wickspinner.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function WickSpinnerMaker.update(dt) if not _G.state then return end; WickSpinnerMaker.dayTimer=WickSpinnerMaker.dayTimer+dt; if WickSpinnerMaker.dayTimer>=30 then WickSpinnerMaker.dayTimer=0; for i=#WickSpinnerMaker.activeMaking,1,-1 do local m=WickSpinnerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WickSpinnerMaker.completeMaking(m); table.remove(WickSpinnerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WickSpinnerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WickSpinnerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WickSpinnerMaker.getStats() return {ironStock=WickSpinnerMaker.ironStock,bronzeStock=WickSpinnerMaker.bronzeStock,woodStock=WickSpinnerMaker.woodStock,leatherStock=WickSpinnerMaker.leatherStock,silverStock=WickSpinnerMaker.silverStock,goldStock=WickSpinnerMaker.goldStock,jewelStock=WickSpinnerMaker.jewelStock,pearlStock=WickSpinnerMaker.pearlStock,productStock=WickSpinnerMaker.productStock,numBuildings=#WickSpinnerMaker.buildings,hasMaker=WickSpinnerMaker.maker~=nil,makerName=WickSpinnerMaker.maker and WickSpinnerMaker.maker.name or "—",makerSkill=WickSpinnerMaker.maker and WickSpinnerMaker.maker.skill or 0,activeMaking=#WickSpinnerMaker.activeMaking,totalProducts=WickSpinnerMaker.totalProducts} end
return WickSpinnerMaker
